// Builds src/data/stories.generated.ts from the app's own series files, so
// the website and the app can never drift apart.
//
//   npm run gen:stories
//
// Reads ../lib/models/series/*.dart (themselves generated by
// tools/gen_series.dart) and keeps what a web page needs: the series, its
// episodes, their length, and where a free preview stops.

import { readFileSync, writeFileSync, readdirSync, mkdirSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const seriesDir = join(here, '..', '..', 'lib', 'models', 'series');
const outFile = join(here, '..', 'src', 'data', 'stories.generated.ts');

// The end-of-episode challenges, keyed by story id, built by
// tools/extract_challenges.mjs. Absent on a fresh clone until that has run.
const challengesFile = join(here, '..', '..', 'tools', 'challenges.json');
const challenges = {};
try {
  const byseries = JSON.parse(readFileSync(challengesFile, 'utf8'));
  for (const [seriesId, list] of Object.entries(byseries)) {
    list.forEach((c, i) => {
      if (!c) return;
      const episodeId = `${seriesId}_${String(i + 1).padStart(2, '0')}`;
      challenges[episodeId] = {
        title: c.title,
        mission: c.mission,
        ...(c.reflection ? { reflection: c.reflection } : {}),
        ...(c.levelUp ? { levelUp: c.levelUp } : {}),
      };
    });
  }
} catch {
  console.warn('tools/challenges.json not found — pages will have no challenge');
}

/** `'Rashid\'s Salam'` -> `Rashid's Salam` */
const unquote = (s) => s.replace(/\\(['"$])/g, '$1');

function field(block, name) {
  const m = block.match(
    new RegExp(`${name}:\\s*'((?:[^'\\\\]|\\\\.)*)'`, 's'),
  );
  return m ? unquote(m[1]) : null;
}

// The spoken welcome that opens a series, from lib/models/series_meet.dart.
// It is shaped as an episode so the site's player takes it unchanged, with no
// preview limit: a welcome plays in full for everyone.
const welcomes = {};
{
  const src = readFileSync(
    join(here, '..', '..', 'lib', 'models', 'series_meet.dart'),
    'utf8',
  );
  const entry =
    /'([a-z_]+)': MeetTheSeries\(\s*track: Story\(([\s\S]*?)\),\s*length: Duration\(milliseconds: (\d+)\)/g;
  for (const [, seriesId, track, ms] of src.matchAll(entry)) {
    welcomes[seriesId] = {
      id: field(track, 'id'),
      title: field(track, 'title'),
      audioKey: (field(track, 'audioAsset') ?? '').replace(
        /^assets\/audio\//,
        '',
      ),
      durationMs: Number(ms),
      previewEndMs: null,
      captions: [],
      challenge: null,
    };
  }
}

/** Splits the `episodes: [...]` list into one text block per Story(...). */
function episodeBlocks(src) {
  const start = src.indexOf('episodes: [');
  if (start < 0) return [];
  return src
    .slice(start)
    .split(/\n {4}Story\(/)
    .slice(1);
}

function parseSeries(file) {
  const src = readFileSync(join(seriesDir, file), 'utf8');
  const header = src.slice(0, src.indexOf('episodes: ['));

  const episodes = episodeBlocks(src).map((block, i) => {
    const lines = [
      ...block.matchAll(
        // `text:` may sit on its own line: dart format wraps the long
        // lines onto the next one, which is most of the story's prose.
        /start: Duration\(milliseconds: (\d+)\),\s*end: Duration\(milliseconds: (\d+)\),\s*text:\s*'((?:[^'\\]|\\.)*)'/gs,
      ),
    ].map((m) => ({
      startMs: Number(m[1]),
      endMs: Number(m[2]),
      text: unquote(m[3]),
    }));
    // A line the pattern above cannot read would vanish from the website
    // without a trace, so stop rather than ship a story with holes in it.
    const declared = (block.match(/CaptionLine\(/g) ?? []).length;
    if (declared !== lines.length) {
      throw new Error(
        `${file} episode ${i + 1}: read ${lines.length} of ${declared} caption lines`,
      );
    }

    const ends = lines.map((l) => l.endMs);
    const durationMs = ends.length ? ends[ends.length - 1] : 0;
    // The same rule the app uses: a free listener hears episode one up to
    // the end of the caption line that crosses the halfway point.
    const half = Math.floor(durationMs / 2);
    const previewEndMs = i === 0
      ? (ends.find((e) => e >= half) ?? half)
      : null;
    const audioAsset = field(block, 'audioAsset') ?? '';

    const id = field(block, 'id');

    return {
      id,
      title: field(block, 'title'),
      audioKey: audioAsset.replace(/^assets\/audio\//, ''),
      durationMs,
      previewEndMs,
      // The challenge the episode closes on — only for the episode the
      // website may actually play. The rest belong to the app, the same way
      // the words below do.
      challenge: previewEndMs == null ? null : (challenges[id] ?? null),
      // The read-along text, kept only for the part the website may play.
      captions:
        previewEndMs == null
          ? []
          : lines.filter((l) => l.endMs <= previewEndMs),
    };
  });

  return {
    id: field(header, 'id'),
    title: field(header, 'title'),
    description: field(header, 'description'),
    language: header.includes('StoryLanguage.urdu') ? 'urdu' : 'english',
    category: header.includes('StoryCategory.prophets') ? 'prophets' : 'moral',
    // assets/covers/respect.webp -> respect
    cover: (field(header, 'coverAsset') ?? '').replace(
      /^assets\/covers\/(.+)\.webp$/,
      '$1',
    ),
    welcome: welcomes[field(header, 'id')] ?? null,
    episodes,
  };
}

const all = readdirSync(seriesDir)
  .filter((f) => f.endsWith('.dart'))
  .map(parseSeries)
  // English first, then Urdu; Prophets before moral series, as in the app.
  .sort((a, b) =>
    a.language === b.language
      ? a.category === b.category
        ? 0
        : a.category === 'prophets'
          ? -1
          : 1
      : a.language === 'english'
        ? -1
        : 1,
  );

const banner = `// GENERATED by scripts/gen-stories.mjs from the app's series files.
// Do not edit by hand: run \`npm run gen:stories\` instead.

import type { Series } from '@/data/types';

export const allSeries: Series[] = `;

mkdirSync(dirname(outFile), { recursive: true });
writeFileSync(outFile, banner + JSON.stringify(all, null, 2) + ';\n');

const episodes = all.reduce((n, s) => n + s.episodes.length, 0);
console.log(`wrote ${all.length} series, ${episodes} episodes`);
